#'
#' c_ecdf_predict_less(3.01,x_s, p_s)
#' c_ecdf_predict_less(3,x_s, p_s)
#' c_ecdf_predict_less(2.99,x_s, p_s)
#'
#' @export
c_ecdf_predict_less <- function(z, x_sorted, p_sorted) {
    .Call(`_infuse_c_ecdf_predict_less`, z, x_sorted, p_sorted)
}

#' Extend the tail of a distribution using Generalized Pareto Distribution (GPD)
#'
#' @description This function takes existing observation vectors and extends
#' them by generating extra values based on GPD parameters. It combines the
#' original data with newly generated tail data.
#'
#' @param uni A NumericVector of existing observation values.
#' @param w A NumericVector of existing probabilities/weights.
#' @param mlesi Double; the scale parameter for the GPD.
#' @param mlesh Double; the shape parameter for the GPD.
#' @param extra_n Double; the number of extra points to generate for the tail.
#'
#' @return A named list containing:
#' \itemize{
#'   \item \code{uni}: A combined numeric vector of original and extended values.
#'   \item \code{w}: A combined numeric vector of associated probabilities/weights.
#' }
#'
#'
#' @examples
#' \dontrun{
#' library(data.table)
#' data(ipilimumab)
#' dat <- as.data.table(ipilimumab)
#'
#' #########################################################
#' # Example 1: Ipilimumab Arm Tail Extension
#' #########################################################
#'
#' # Read the data
#' X <- dat[arm == "ipilimumab", time]
#' Xs <- dat[arm == "ipilimumab", event]
#'
#' # Artificially censor the last few events to illustrate functionality
#' wher <- X > 26
#' Xs[wher] <- 0
#' X[wher] <- X[wher][1]
#'
#' # Estimate the ECDF using Kaplan-Meier logic
#' fit <- c_ecdf_plus(X, Xs)
#' or <- fit$o
#'
#' # Plot the initial ECDF
#' plot(X[or], fit$p[or], type = "s", ylim = c(0, 1),
#'      main = "GPD Tail Extension (Ipilimumab)")
#' abline(h = 1, lty = 3)
#'
#' # Estimate scale and shape parameters for the GPD
#' p <- param_gpd(X[or], Xs[or])
#'
#' # Extend the tail using GPD parameters
#' uni <- X[or]
#' w <- fit$p[or]
#' ta <- c_extendtail(uni, w, p$mlesi, p$mlesh, p$extra_n)
#'
#' # Visualize the extension in red
#' plot(w ~ uni, data = ta, type = "s", col = "red", ylim = c(0, 1),
#'      xlim = c(0, max(ta$uni)), xlab = "Time", ylab = "ECDF")
#' points(w ~ uni, type = "s")
#' abline(h = 1, lty = 3)
#'
#' #########################################################
#' # Example 2: Placebo Arm with Custom Extension Lengths
#' #########################################################
#'
#' # Read the data
#' X <- dat[arm == "placebo", time]
#' Xs <- dat[arm == "placebo", event]
#'
#' # Censor data after time 10
#' wher <- X > 10
#' Xs[wher] <- 0
#' X[wher] <- X[wher][1]
#'
#' # Estimate ECDF and GPD parameters
#' fit <- c_ecdf_plus(X, Xs)
#' or <- fit$o
#' p <- param_gpd(X[or], Xs[or])
#'
#' # Extend the tail with 10 simulated values
#' ta10 <- c_extendtail(X[or], fit$p[or], p$mlesi, p$mlesh, extra_n = 10)
#'
#' # Plot 10-value extension
#' plot(w ~ uni, data = ta10, type = "s", col = "red", ylim = c(0, 1),
#'      xlim = c(0, max(ta10$uni)), main = "Extension: 10 values")
#' points(X[or], fit$p[or], type = "s")
#' abline(h = 1, lty = 3)
#'
#' # Extend the tail with only 5 values
#' ta5 <- c_extendtail(X[or], fit$p[or], p$mlesi, p$mlesh, extra_n = 5)
#'
#' # Plot 5-value extension
#' plot(w ~ uni, data = ta5, type = "s", col = "blue", ylim = c(0, 1),
#'      xlim = c(0, max(ta5$uni)), main = "Extension: 5 values")
#' points(X[or], fit$p[or], type = "s")
#' abline(h = 1, lty = 3)
#' }
#' @export
c_extendtail <- function(uni, w, mlesi, mlesh, extra_n) {
    .Call(`_infuse_c_extendtail`, uni, w, mlesi, mlesh, extra_n)
}

#' Calculate Favorable Outcome Estimand A with Censoring and Margin Shift
#'
#' @description
#' Computes the population-level favorable outcome probability \eqn{A = P(X \ge Y + \lambda)}
#' between two treatment arms ("X" and "Y"). It handles continuous or time-to-event
#' data with optional right-censoring via non-parametric survival/ECDF estimation.
#'
#' @param arm A \code{CharacterVector} specifying group allocation (must contain \code{"X"} or \code{"Y"}).
#' @param time A \code{NumericVector} of observed event or censoring times.
#' @param status An \code{IntegerVector} indicating event status (typically \code{1} for observed event, \code{0} for censored).
#' @param lambda_val A \code{double} specifying a margin or threshold shift (\eqn{\lambda}) applied to arm Y's outcomes.
#'
#' @details
#' The function executes the following steps:
#' \enumerate{
#'   \item \bold{Complete Case Filtering:} Automatically filters out observations where \code{arm}, \code{time}, or \code{status} contains \code{NA}.
#'   \item \bold{Group-wise Non-parametric Estimation:} Fits Kaplan-Meier / modified ECDF step functions using \code{\link{c_ecdf_plus}} separately for arm X and arm Y.
#'   \item \bold{Predictive Evaluation:} Evaluates the survival probability \eqn{S_X(t) = P(X \ge t)} at shifted time points \eqn{t_Y + \lambda} via \code{\link{c_ecdf_predict_less}}.
#'   \item \bold{Weighted Integration:} Computes the overall estimand \eqn{A = \sum S_X(Y_j + \lambda) \cdot w_{Y, j}} using the survival jumps/weights (\eqn{w_Y}).
#' }
#'
#' @return A \code{double} representing the favorable outcome probability \eqn{A}.
#' Returns \code{NA_REAL} if either treatment group contains zero complete cases.
#'
#' @export
c_fav <- function(arm, time, status, lambda_val) {
    .Call(`_infuse_c_fav`, arm, time, status, lambda_val)
}

